import{d as h,C as n,o as g,c as u,a3 as i,E as s,j as a,a as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·述而","description":"《论语》第 7 篇「述而」——三十八章原文与导读。述而不作、学而不厌诲人不倦、不愤不启、饭疏食饮水、三人行必有我师。","frontmatter":{"title":"论语·述而","description":"《论语》第 7 篇「述而」——三十八章原文与导读。述而不作、学而不厌诲人不倦、不愤不启、饭疏食饮水、三人行必有我师。","category":"guide","aliases":["述而","述而篇","述而第七","论语述而","lunyu 述而"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-07.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-07.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/lunyu/chapter-07.md"},w=h({...m,setup(b){const t=[{id:"yi",label:"一、述而不作",showLabel:!0,sentences:[["子曰：“",{text:"述而不作",glossary:"shuerbuzuo"},"，信而好古，窃比于我",{text:"老彭",glossary:"laopeng"},"。”"]],note:"「述而不作，信而好古」——只传述而不创作，信实而好古；「窃比于我老彭」——私下自比于老彭（殷商之贤大夫）。此为全篇自述为学之态。"},{id:"er",label:"二、学而不厌，诲人不倦",showLabel:!0,sentences:[["子曰：“默而",{text:"识",glossary:"zhi-ji"},"之，学而不厌，诲人不倦，何有于我哉？”"]],note:"「默而识之」（默记于心），「学而不厌，诲人不倦」——学习不厌足，教人不倦怠；「何有于我哉」——这些我做到了哪些呢？自谦之辞。"},{id:"san",label:"三、是吾忧也",showLabel:!0,sentences:[["子曰：“德之不修，学之不讲，闻义不能",{text:"徙",glossary:"xi"},"，不善不能改，是吾忧也。”"]],note:"「德之不修，学之不讲，闻义不能徙，不善不能改，是吾忧也」——德行不修，学问不讲，闻义不能迁从，有不善不能改：此四者是我的忧虑。"},{id:"si",label:"四、子之燕居",showLabel:!0,sentences:[["子之燕居，",{text:"申申如",glossary:"shenshenru"},"也，",{text:"夭夭如",glossary:"yaoyaoru"},"也。"]],note:"「子之燕居，申申如也，夭夭如也」——孔子闲居时，容貌舒展（申申），神色和悦（夭夭）。写其闲居之气象。"},{id:"wu",label:"五、不复梦见周公",showLabel:!0,sentences:[["子曰：“甚矣吾衰也！久矣吾不复梦见周公。”"]],note:"「甚矣吾衰也！久矣吾不复梦见周公」——我衰老得厉害啊！很久没有再梦见周公了。周公是孔子所仰慕之圣人，不复梦见，实为道不行之慨。"},{id:"liu",label:"六、志于道，据于德",showLabel:!0,sentences:[["子曰：“志于道，据于德，依于仁，游于艺。”"]],note:"「志于道，据于德，依于仁，游于艺」——志向在道，执守在德，依倚在仁，游习于六艺。四句为孔子为学之总纲。"},{id:"qi",label:"七、束脩以上",showLabel:!0,sentences:[["子曰：“自行",{text:"束脩",glossary:"shuxiu"},"以上，吾未尝无诲焉。”"]],note:"「自行束脩以上，吾未尝无诲焉」——凡自愿送上一束干肉（束脩＝十条干肉，薄礼）为贽的，我没有不教诲的。即有教无类。"},{id:"ba",label:"八、不愤不启，不悱不发",showLabel:!0,sentences:[["子曰：“不",{text:"愤",glossary:"fen"},"不启，不",{text:"悱",glossary:"fei"},"不发，举一隅不以三隅反，则不复也。”"]],note:"「不愤不启，不悱不发」——不到他心求通而不得时不去开导（愤＝心求通而未得），不到他口欲言而不能时不去启发（悱＝口欲言而未能）；「举一隅不以三隅反，则不复也」——举出一角而不能推知其余三角，便不再教。此为启发式教学的经典出处。"},{id:"jiu",label:"九、子食于有丧者之侧",showLabel:!0,sentences:[["子食于有丧者之侧，未尝饱也。"]],note:"「子食于有丧者之侧，未尝饱也」——孔子在有丧者之侧进食，从未吃饱过。见其同哀之心。"},{id:"shi",label:"十、于是日哭，则不歌",showLabel:!0,sentences:[["子于是日哭，则不歌。"]],note:"「子于是日哭，则不歌」——孔子在这一日哭过，便不再唱歌。见其哀乐不相杂。"},{id:"shiyi",label:"十一、临事而惧，好谋而成",showLabel:!0,sentences:[["子谓颜渊曰：“用之则行，舍之则藏，惟我与尔有是夫！”子路曰：“子行三军，则谁与？”子曰：“",{text:"暴虎冯河",glossary:"baohupinghe"},"，死而无悔者，吾不与也。必也临事而惧，好谋而成者也。”"]],note:"孔子对颜渊说：「用之则行，舍之则藏，惟我与尔有是夫」——用我便行其道，不用我便藏其身，只有我和你能如此吧！子路问：「子行三军，则谁与」——您若统率三军，和谁同往？孔子说：「暴虎冯河，死而无悔者，吾不与也」（暴虎＝徒手搏虎，冯河＝徒步涉河，喻徒逞血气之勇），「必也临事而惧，好谋而成者也」——必定是临事而戒惧、好谋而能成事的人。"},{id:"shier",label:"十二、执鞭之士",showLabel:!0,sentences:[["子曰：“富而可求也，虽执鞭之士，吾亦为之。如不可求，从吾所好。”"]],note:"「富而可求也，虽执鞭之士，吾亦为之」——若富贵可以求得，纵然做执鞭的贱职，我也愿意；「如不可求，从吾所好」——若不可求，便随我所好。"},{id:"shisan",label:"十三、子之所慎",showLabel:!0,sentences:[["子之所慎：",{text:"齐（斋）",glossary:"zhai"},"，战，疾。"]],note:"「子之所慎：齐（斋），战，疾」——孔子所慎重对待者有三：斋戒、战争、疾病。"},{id:"shisi",label:"十四、三月不知肉味",showLabel:!0,sentences:[["子在齐闻《韶》，三月不知肉味，曰：“不图为乐之至于斯也。”"]],note:"「子在齐闻《韶》，三月不知肉味」——孔子在齐国听到《韶》乐，三个月尝不出肉味；「曰：不图为乐之至于斯也」——说：想不到音乐能到这般境界。"},{id:"shiwu",label:"十五、求仁而得仁",showLabel:!0,sentences:[["冉有曰：“夫子为卫君乎？”子贡曰：“诺，吾将问之。”入，曰：“伯夷、叔齐何人也？”曰：“古之贤人也。”曰：“怨乎？”曰：“求仁而得仁，又何怨？”出，曰：“夫子不为也。”"]],note:"冉有问：「夫子为卫君乎」——老师会帮助卫君（出公辄）吗？子贡说「我去问」。入内问：「伯夷、叔齐何人也？」孔子答「古之贤人也」；问「怨乎」，答：「求仁而得仁，又何怨？」子贡出来说：「夫子不为也」——老师不会帮卫君。盖伯夷叔齐让国而逃，卫君则父子争国，以此反衬。"},{id:"shiliu",label:"十六、于我如浮云",showLabel:!0,sentences:[["子曰：“饭疏食饮水，",{text:"曲肱而枕之",glossary:"qugong"},"，乐亦在其中矣。不义而富且贵，于我如浮云。”"]],note:"「饭疏食饮水，曲肱而枕之，乐亦在其中矣」——吃粗饭、喝冷水，弯臂作枕，乐趣亦在其中；「不义而富且贵，于我如浮云」——不合义而得来的富贵，对我如天上浮云。"},{id:"shiqi",label:"十七、五十以学《易》",showLabel:!0,sentences:[["子曰：“加我数年，五十以学《易》，可以无大过矣。”"]],note:"「加我数年，五十以学《易》，可以无大过矣」——再给我几年，到五十岁去学《易》，便可以没有大过错了。（一说「五十」为「卒」之讹。）"},{id:"shiba",label:"十八、子所雅言",showLabel:!0,sentences:[["子所",{text:"雅言",glossary:"yayan"},"，《诗》、《书》、执礼，皆雅言也。"]],note:"「子所雅言，《诗》、《书》、执礼，皆雅言也」——孔子用雅言（正音，当时通行之官话）之时，是读《诗》《书》与行礼之际，皆用雅言。"},{id:"shijiu",label:"十九、发愤忘食，乐以忘忧",showLabel:!0,sentences:[["叶公问孔子于子路，子路不对。子曰：“女奚不曰：其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。”"]],note:"叶公问子路：孔子是怎样的人？子路不答。孔子说：「女（汝）奚不曰」——你何不这样说：「其为人也，发愤忘食，乐以忘忧，不知老之将至云尔」——他的为人，发愤用功至于忘食，快乐得忘了忧愁，不知衰老将至，如此而已。"},{id:"ershi",label:"二十、我非生而知之者",showLabel:!0,sentences:[["子曰：“我非生而知之者，好古，敏以求之者也。”"]],note:"「我非生而知之者，好古，敏以求之者也」——我不是生来就有知识的人，而是好古而勤敏求索的人。"},{id:"ershiyi",label:"二十一、子不语怪力乱神",showLabel:!0,sentences:[["子不语怪、力、乱、神。"]],note:"「子不语怪、力、乱、神」——孔子不谈论怪异、勇力、悖乱、鬼神。四字见孔子言说之界。"},{id:"ershier",label:"二十二、三人行，必有我师",showLabel:!0,sentences:[["子曰：“三人行，必有我师焉。择其善者而从之，其不善者而改之。”"]],note:"「三人行，必有我师焉」——三人同行，其中必有可为我师者；「择其善者而从之，其不善者而改之」——择其善者学之，见其不善者则自省而改。"},{id:"ershisan",label:"二十三、天生德于予",showLabel:!0,sentences:[["子曰：“天生德于予，",{text:"桓魋",glossary:"huantui"},"其如予何？”"]],note:"「天生德于予，桓魋其如予何」——上天赋德于我，桓魋能把我怎样？此为孔子遭遇宋司马桓魋之难时语。"},{id:"ershisi",label:"二十四、吾无隐乎尔",showLabel:!0,sentences:[["子曰：“二三子以我为隐乎？吾无隐乎尔！吾无行而不与二三子者，是丘也。”"]],note:"「二三子以我为隐乎？吾无隐乎尔」——你们以为我有所隐瞒吗？我对你们毫无隐瞒。「吾无行而不与二三子者，是丘也」——我没有一事不与你们同在，这就是我孔丘。"},{id:"ershiwu",label:"二十五、子以四教",showLabel:!0,sentences:[["子以四教：文，行，忠，信。"]],note:"「子以四教：文，行，忠，信」——孔子以四者教人：文献、德行、忠、信。"},{id:"ershiliu",label:"二十六、得见有恒者",showLabel:!0,sentences:[["子曰：“圣人，吾不得而见之矣；得见君子者斯可矣。”子曰：“善人，吾不得而见之矣；得见有恒者斯可矣。",{text:"亡而为有",glossary:"wangeryou"},"，虚而为盈，约而为",{text:"泰",glossary:"tai"},"，难乎有恒矣。”"]],note:"「圣人，吾不得而见之矣；得见君子者斯可矣」——圣人我见不到了，能见到君子就可以了。「善人，吾不得而见之矣；得见有恒者斯可矣」——善人我见不到了，能见到有恒心者就可以了。「亡而为有，虚而为盈，约而为泰，难乎有恒矣」——没有装作有、空虚装作充实、穷困装作奢泰，便难有恒。"},{id:"ershiqi",label:"二十七、钓而不纲",showLabel:!0,sentences:[["子钓而不",{text:"纲",glossary:"gang"},"，",{text:"弋",glossary:"yi-she"},"不射宿。"]],note:"「子钓而不纲，弋不射宿」——孔子钓鱼而不用大网（纲），射鸟而不射归巢栖宿之鸟。见其取物有节、心存仁厚。"},{id:"ershiba",label:"二十八、多闻，择其善者而从之",showLabel:!0,sentences:[["子曰：“盖有不知而作之者，我无是也。多闻，择其善者而从之；多见而识之，知之次也。”"]],note:"「盖有不知而作之者，我无是也」——大概有不知而妄自造作的人，我没有这样。「多闻，择其善者而从之；多见而识之，知之次也」——多听，择其善者而从；多见而记之：这是次一等的知（非生知）。"},{id:"ershijiu",label:"二十九、与其进也，不与其退也",showLabel:!0,sentences:[["互乡难与言，童子见，门人惑。子曰：“与其进也，不与其退也，唯何甚？人洁己以进，与其洁也，不保其往也。”"]],note:"互乡之人难以交谈，其地一童子来见，门人不解。孔子说：「与其进也，不与其退也，唯何甚」——应许他上进，不应许他后退，何必做得太过？「人洁己以进，与其洁也，不保其往也」——人洁身而来，就当许其洁，不必追究他的过往。"},{id:"sanshi",label:"三十、我欲仁，斯仁至矣",showLabel:!0,sentences:[["子曰：“仁远乎哉？我欲仁，斯仁至矣。”"]],note:"「仁远乎哉？我欲仁，斯仁至矣」——仁离我们远吗？我想要仁，仁就到了。言仁由己而不由人。"},{id:"sanshiyi",label:"三十一、丘也幸",showLabel:!0,sentences:[["陈司败问：“昭公知礼乎？”孔子曰：“知礼。”孔子退，揖巫马期而进之，曰：“吾闻君子不党，君子亦党乎？君取于吴，为同姓，谓之吴孟子。君而知礼，孰不知礼？”巫马期以告。子曰：“丘也幸，苟有过，人必知之。”"]],note:"陈司败问：「昭公知礼乎」——鲁昭公懂礼吗？孔子答「知礼」。孔子退后，陈司败向巫马期作揖而进言：「吾闻君子不党，君子亦党乎」——我听说君子不偏私，君子也偏私吗？「君取于吴，为同姓，谓之吴孟子」——鲁君娶吴国之女，因同为姬姓，讳称「吴孟子」——如此还懂礼，谁不懂礼？巫马期以告，孔子说：「丘也幸，苟有过，人必知之」——我孔丘有幸，一旦有过，别人必定知道。"},{id:"sanshier",label:"三十二、子与人歌而善",showLabel:!0,sentences:[["子与人歌而善，必使反之，而后和之。"]],note:"「子与人歌而善，必使反之，而后和之」——孔子与人唱歌，若唱得好，必请对方再唱一遍，然后自己才和唱。见其虚己乐善。"},{id:"sanshisan",label:"三十三、躬行君子",showLabel:!0,sentences:[["子曰：“文，莫吾犹人也。躬行君子，则吾未之有得。”"]],note:"「文，莫吾犹人也」——论文献之学，大概我与别人差不多；「躬行君子，则吾未之有得」——至于亲身践行君子之德，我还没有做到。"},{id:"sanshisi",label:"三十四、为之不厌，诲人不倦",showLabel:!0,sentences:[["子曰：“若圣与仁，则吾岂敢？抑为之不厌，诲人不倦，则可谓云尔已矣。”公西华曰：“正唯弟子不能学也。”"]],note:"「若圣与仁，则吾岂敢」——至于圣与仁，我怎么敢当？「抑为之不厌，诲人不倦，则可谓云尔已矣」——只是做而不厌、教而不倦，可说是如此罢了。公西华曰：「正唯弟子不能学也」——这正是弟子们学不到的。"},{id:"sanshiwu",label:"三十五、丘之祷久矣",showLabel:!0,sentences:[["子疾病，子路请祷。子曰：“有诸？”子路对曰：“有之。《诔》曰：‘祷尔于上下神祇。’”子曰：“丘之祷久矣。”"]],note:"孔子病重，子路请为之祈祷。孔子说：「有诸」——有这回事吗？子路答：「有之。《诔》曰：祷尔于上下神祇」——有；《诔》文说「为你向上下神祇祈祷」。孔子说：「丘之祷久矣」——我孔丘祈祷已经很久了（谓平日行事无愧，即是久祷）。"},{id:"sanshiliu",label:"三十六、奢则不孙，俭则固",showLabel:!0,sentences:[["子曰：“奢则不",{text:"孙",glossary:"xun"},"，俭则固。与其不孙也，宁固。”"]],note:"「奢则不孙（逊），俭则固」——奢侈便显得不谦顺，俭啬便显得固陋；「与其不孙也，宁固」——与其不逊，宁可固陋。"},{id:"sanshiqi",label:"三十七、君子坦荡荡",showLabel:!0,sentences:[["子曰：“君子坦荡荡，小人长",{text:"戚戚",glossary:"qiqi"},"。”"]],note:"「君子坦荡荡，小人长戚戚」——君子心地平坦宽广，小人则常常忧愁局促。"},{id:"sanshiba",label:"三十八、温而厉，威而不猛",showLabel:!0,sentences:[["子温而厉，威而不猛，恭而安。"]],note:"「子温而厉，威而不猛，恭而安」——孔子温和而严厉，有威仪而不凶猛，恭敬而安详。三对相反的品质兼而有之，既为全篇之收，也是孔子的气象。"}],r=[{id:"shuerbuzuo",term:"述而不作",pinyin:"shù ér bù zuò",meaning:"只阐述传承，不自己创制。述：传述；作：创作。孔子自谦，也表明其对传统的态度。"},{id:"laopeng",term:"老彭",pinyin:"lǎo péng",meaning:"殷商时的贤大夫（一说指老子与彭祖）。孔子自比于他，即自居于「传述者」之位。"},{id:"zhi-ji",term:"识",pinyin:"zhì",meaning:"同「志」，记住。默而识之：默默记在心里。"},{id:"xi",term:"徙",pinyin:"xǐ",meaning:"迁移、跟从。闻义不能徙：听到该做的事却不能照做。"},{id:"shenshenru",term:"申申如",pinyin:"shēn shēn rú",meaning:"容貌舒展整饬的样子。"},{id:"yaoyaoru",term:"夭夭如",pinyin:"yāo yāo rú",meaning:"神色和悦舒缓的样子。这两句写孔子闲居时的气象。"},{id:"shuxiu",term:"束脩",pinyin:"shù xiū",meaning:"一束干肉（十条），古代最薄的见面礼。自行束脩以上：只要自愿带一点薄礼来求教。"},{id:"fen",term:"愤",pinyin:"fèn",meaning:"心里想弄通而还未通的样子（不是愤怒）。不愤不启：不到他苦思不得时，不去开导。"},{id:"fei",term:"悱",pinyin:"fěi",meaning:"想说而说不出来的样子。不悱不发：不到他想说而说不出时，不去启发。"},{id:"baohupinghe",term:"暴虎冯河",pinyin:"bào hǔ píng hé",meaning:"暴虎：空手打虎；冯河：徒步涉河。喻有勇无谋的蛮干。"},{id:"zhai",term:"齐",pinyin:"zhāi",meaning:"同「斋」，斋戒（祭前洁身诚心）。"},{id:"qugong",term:"曲肱而枕之",pinyin:"qū gōng ér zhěn zhī",meaning:"弯起胳膊当枕头。状生活清贫而自得。"},{id:"yayan",term:"雅言",pinyin:"yǎ yán",meaning:"当时通行的标准语（相当于「官话」）。孔子诵读《诗》《书》与行礼时用雅言。"},{id:"huantui",term:"桓魋",pinyin:"huán tuí",meaning:"宋国司马，曾想加害孔子。孔子此语表示自信于天命。"},{id:"wangeryou",term:"亡而为有",pinyin:"wáng ér wéi yǒu",meaning:"没有却装作有。亡：同「无」。下文「虚而为盈，约而为泰」同此，皆言虚饰。"},{id:"tai",term:"泰",pinyin:"tài",meaning:"宽绰、奢侈。约而为泰：穷困却装阔。"},{id:"gang",term:"纲",pinyin:"gāng",meaning:"大网（用大网横断水流捕鱼）。钓而不纲：只钓鱼，不用大网一网打尽。"},{id:"yi-she",term:"弋",pinyin:"yì",meaning:"用带生丝的箭射鸟。弋不射宿：不射已归巢栖息的鸟。二者皆见其取物有节。"},{id:"xun",term:"孙",pinyin:"xùn",meaning:"同「逊」，顺、恭顺（此指骄纵不顺）。奢则不孙：奢侈就不恭顺。"},{id:"qiqi",term:"戚戚",pinyin:"qī qī",meaning:"忧惧、局促不安的样子。"}];return(y,e)=>{const l=n("DaoTextReading"),o=n("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=i('<h1 id="论语·述而" tabindex="-1">论语·述而 <a class="header-anchor" href="#论语·述而" aria-label="Permalink to &quot;论语·述而&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《述而》是《论语》中<strong>最能见孔子自述</strong>的一篇。他说自己「述而不作，信而好古」，说「我非生而知之者，好古，敏以求之者也」，说「若圣与仁，则吾岂敢？抑为之不厌，诲人不倦」——<strong>一再地把自己放在一个传承者和学习者的位置上</strong>。</p><p>这一篇里留下了许多名句：学而不厌、诲人不倦、不愤不启、不悱不发、三人行必有我师、饭疏食饮水、不义而富且贵于我如浮云、君子坦荡荡、发愤忘食乐以忘忧。也有侧面写人的：子之燕居（闲居的样子）、子食于有丧者之侧、子与人歌而善、子温而厉威而不猛恭而安——<strong>这些都是《论语》里少见的「孔子的样子」</strong>。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',5)),s(l,{colophon:"述而第七 · 三十八章",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"论语·述而 原文"}),e[1]||(e[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),s(o,{items:[{term:"述而不作",pinyin:["shù","ér","bù","zuò"],meaning:"只阐述传承，不自己创制。述：传述；作：创作。孔子自谦，也表明其对传统的态度。"},{term:"老彭",pinyin:["lǎo","péng"],meaning:"殷商时的贤大夫（一说指老子与彭祖）。孔子自比于他，即自居于「传述者」之位。"},{term:"识",pinyin:["zhì"],meaning:"同「志」，记住。默而识之：默默记在心里。"},{term:"徙",pinyin:["xǐ"],meaning:"迁移、跟从。闻义不能徙：听到该做的事却不能照做。"},{term:"申申如",pinyin:["shēn","shēn","rú"],meaning:"容貌舒展整饬的样子。"},{term:"夭夭如",pinyin:["yāo","yāo","rú"],meaning:"神色和悦舒缓的样子。这两句写孔子闲居时的气象。"},{term:"束脩",pinyin:["shù","xiū"],meaning:"一束干肉（十条），古代最薄的见面礼。自行束脩以上：只要自愿带一点薄礼来求教。"},{term:"愤",pinyin:["fèn"],meaning:"心里想弄通而还未通的样子（不是愤怒）。不愤不启：不到他苦思不得时，不去开导。"},{term:"悱",pinyin:["fěi"],meaning:"想说而说不出来的样子。不悱不发：不到他想说而说不出时，不去启发。"},{term:"暴虎冯河",pinyin:["bào","hǔ","píng","hé"],meaning:"暴虎：空手打虎；冯河：徒步涉河。喻有勇无谋的蛮干。"},{term:"齐",pinyin:["zhāi"],meaning:"同「斋」，斋戒（祭前洁身诚心）。"},{term:"曲肱而枕之",pinyin:["qū","gōng","ér","zhěn","zhī"],meaning:"弯起胳膊当枕头。状生活清贫而自得。"},{term:"雅言",pinyin:["yǎ","yán"],meaning:"当时通行的标准语（相当于「官话」）。孔子诵读《诗》《书》与行礼时用雅言。"},{term:"桓魋",pinyin:["huán","tuí"],meaning:"宋国司马，曾想加害孔子。孔子此语表示自信于天命。"},{term:"亡而为有",pinyin:["wáng","ér","wéi","yǒu"],meaning:"没有却装作有。亡：同「无」。下文「虚而为盈，约而为泰」同此，皆言虚饰。"},{term:"泰",pinyin:["tài"],meaning:"宽绰、奢侈。约而为泰：穷困却装阔。"},{term:"纲",pinyin:["gāng"],meaning:"大网（用大网横断水流捕鱼）。钓而不纲：只钓鱼，不用大网一网打尽。"},{term:"弋",pinyin:["yì"],meaning:"用带生丝的箭射鸟。弋不射宿：不射已归巢栖息的鸟。二者皆见其取物有节。"},{term:"孙",pinyin:["xùn"],meaning:"同「逊」，顺、恭顺（此指骄纵不顺）。奢则不孙：奢侈就不恭顺。"},{term:"戚戚",pinyin:["qī","qī"],meaning:"忧惧、局促不安的样子。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《述而》三十八章，主体是<strong>孔子自述</strong>。他反复说明自己是谁、在做什么：一个「述而不作」的传述者，一个「非生而知之」的求学者，一个「为之不厌、诲人不倦」的教书人，一个「发愤忘食、乐以忘忧」的人。</p><p>这一篇的写法很特别——它很少讲道理，多在<strong>亮态度</strong>。富贵「于我如浮云」，粗茶淡饭「乐亦在其中」，见到有丧事的人就吃不饱，哭过的那天就不唱歌。还有几章直接写他的神情举止：燕居时申申如、夭夭如；温和而严肃，有威而不凶猛，恭敬而安详。</p><p>最后几章尤其诚：说自己「躬行君子，则吾未之有得」；病中子路请祷，他说「丘之祷久矣」；谈到圣与仁，他说「吾岂敢」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给出了一种「学习者的姿态」</strong>：「述而不作」不是保守，是<strong>认清自己在传统中的位置</strong>——先把前人的东西吃透，再谈创造。「我非生而知之者」更是把天才论直接否掉了。</li><li><strong>它把「教」与「学」融为一体</strong>：「学而不厌，诲人不倦」——<strong>学不厌是向内的动力，诲不倦是向外的付出</strong>。这两件事同时成立，人才不会枯竭。</li><li><strong>它给出了最好的启发式教学法</strong>：「不愤不启，不悱不发，举一隅不以三隅反，则不复也」——<strong>教的时机比教的内容更重要</strong>。</li><li><strong>它示范了什么叫「自我要求的诚实」</strong>：孔子坦承自己「躬行君子，未之有得」，「若圣与仁，则吾岂敢」。<strong>真站得高的人，往往对自己评价最低。</strong></li><li><strong>它留下了一段豁达的日常</strong>：「饭疏食饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。」——<strong>贫富是外物，乐在自己心里。</strong></li><li><strong>它有几个侧面把孔子写活了</strong>：与人唱歌唱得好的话，一定请人再唱一遍然后自己和；闲居时舒展和悦；温和而严肃，有威而不凶猛。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「不愤不启」对待他人的学习</strong>：孩子、下属、伙伴卡住的时候，先等他自己想，别抢着给答案。<strong>给的答案留不住，自己想到的才成自己的。</strong></li><li><strong>把「学不厌、诲不倦」当作做事能量的两个来源</strong>：只学不教容易自嗨，只教不学会被掏空。<strong>两边都保持流动。</strong></li><li><strong>摆正「义」与「富」的顺序</strong>：不是拒绝富贵，是「不义」的富贵不值得求。<strong>心里立了这条线，很多选择会变简单。</strong></li><li><strong>接受自己「还没有做到」</strong>：孔子到老说自己「躬行君子，未之有得」。<strong>把评价自己的尺子放在「做到多少」而不是「知道多少」上。</strong></li><li><strong>用「三人行必有我师」做日常观察</strong>：任何人身上都能找出一件可学的事，任何人身上也都能照出一件该改的事。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《述而》是一篇很「近」的文字。孔子在这里没有批评谁，也没有训示谁，他主要是在说他自己。</p><p>他说自己是个传述者而不是创造者；说自己不是天才，只是喜欢古代的东西、肯下功夫去追；说自己一旦发愤用功就忘了吃饭，一快乐起来就忘了忧愁，连老了都察觉不到。</p><p>他也不客气地说自己的短处：说到身体力行做君子，他说「吾未之有得」；说到圣与仁，他说「吾岂敢」。他对学生坦白——「吾无隐乎尔」，我没有什么瞒着你们的。</p><p>其余几章，是他的日常：在有丧事的人旁边吃饭会吃不饱；哭过的那天就不唱歌；和人唱歌，人家唱得好，一定请人再唱一遍，然后自己跟着和。</p><p>一个把「学」当作一生的事、并且诚实到近乎苛刻的人——这就是这一篇里的孔子。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「述而不作」——我做事时，是想先学透，还是急着做出「自己的东西」？哪一个更靠得住？</li><li>「学而不厌，诲人不倦」——我上一次「教」别人是什么时候？那次我是耐心，还是嫌烦？</li><li>「不愤不启，不悱不发」——我是不是常常在别人还没卡住的时候就抢着给答案？</li><li>「不义而富且贵，于我如浮云」——这句话在今天，我的理解是什么？我心里那条线立住了吗？</li><li>「躬行君子，则吾未之有得」——如果让我诚实地评自己，我是「知道的」多还是「做到的」多？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-06">论语·雍也</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-08">论语·泰伯</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',22))])}}});export{c as __pageData,w as default};
